// Actual API/history + product navigation. Synthetic QA auth and loopback only.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {chromium}=require('/Users/toozservis/Developer/evidence-web-qa-runtime/node_modules/playwright');
const origin=process.env.NOTIFICATION_QA_ORIGIN||'http://127.0.0.1:18920';assert.equal(new URL(origin).hostname,'127.0.0.1');
const out=process.env.NOTIFICATION_QA_OUTPUT||'/Users/toozservis/Developer/evidence-push-admin-delivery-20261105/web-evidence/history';fs.mkdirSync(out,{recursive:true});
(async()=>{const user=(await(await fetch(origin+'/qa/setup')).json()).web.users.user,checks=[],requests=[],errors=[];
 const api=async(url,method='GET',body)=>{const r=await fetch(origin+url,{method,headers:{Authorization:'Bearer '+user.jwt,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();assert(r.ok,JSON.stringify(d));return d;};
 const seed=async(kind,title)=>{const r=await fetch(origin+'/qa/seed-notification?'+new URLSearchParams({group:'web',recipient:'user',kind,required:'false',title,body:title+' — soukromý syntetický obsah.'}),{method:'POST'});const d=await r.json();assert(r.ok,JSON.stringify(d));return d.item;};
 for(const item of (await api('/api/v1/notifications?pending_only=true&limit=100')).items.filter(i=>i.title.startsWith('WEB-NOTICE-QA')||i.body.startsWith('WEB-NOTICE-QA'))){await api('/api/v1/notifications/'+item.id+(item.requires_ack?'/ack':'/dismiss'),'POST',{client_id:crypto.randomUUID()});}
 let all=(await api('/api/v1/notifications?limit=100')).items;while(all.length<33){const item=await seed('announcement','WEB-NOTICE-QA historie '+crypto.randomUUID());const r=await fetch(origin+'/qa/archive-notification?group=web&identifier='+item.id,{method:'POST'});assert(r.ok);all.push(item);}
 const vehicle=await seed('vehicle_update','WEB-NOTICE-QA servisní aktualizace '+crypto.randomUUID());assert(Number.isSafeInteger(vehicle.action.vehicle_id));
 const browser=await chromium.launch({channel:'chrome',headless:true}),contexts=[];let p;
 const make=async(auth=true)=>{const c=await browser.newContext({viewport:{width:1360,height:900},locale:'cs-CZ'});contexts.push(c);await c.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());if(auth)await c.addInitScript(u=>{sessionStorage.setItem('customerWebAccessToken',u.jwt);sessionStorage.setItem('customerWebRole',u.role);},user);const page=await c.newPage();page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>requests.push(new URL(r.url()).pathname));return page;};
 const dialog=()=>p.locator('dialog.notification-dialog');
 const save=async name=>{await p.screenshot({path:path.join(out,name+'.png')});fs.writeFileSync(path.join(out,name+'.txt'),await p.locator('body').innerText());};
 try{
  p=await make();await p.goto(origin+'/web/customer.html');await p.locator('#notification-nav-entry').waitFor();assert.equal(await p.locator('#account-notification-banner').count(),0);await p.locator('#notification-nav-entry').click();await dialog().locator('.notification-card').first().waitFor();assert.equal(await dialog().locator('.notification-card').count(),30);const initial=await dialog().locator('.notification-card').evaluateAll(es=>es.map(e=>e.dataset.notificationId));await dialog().getByRole('button',{name:'Načíst starší oznámení',exact:true}).click();await dialog().locator('.notification-card').nth(30).waitFor();const complete=await dialog().locator('.notification-card').evaluateAll(es=>es.map(e=>e.dataset.notificationId));assert.equal(new Set(complete).size,complete.length);assert(initial.every(id=>complete.includes(id)));checks.push('Actual before_id history pagination retains first page and loads older unique items');await save('01-history-paging');
  const row=dialog().locator('[data-notification-id="'+vehicle.id+'"]');await row.getByRole('button',{name:'Otevřít',exact:true}).click();await dialog().getByText(vehicle.body,{exact:true}).waitFor();for(let n=0;n<70;n++){if((await api('/api/v1/notifications/'+vehicle.id)).item.read_at)break;await new Promise(r=>setTimeout(r,100));}assert((await api('/api/v1/notifications/'+vehicle.id)).item.read_at);assert.equal(await dialog().getByRole('button',{name:'Rozumím',exact:true}).count(),0);assert.equal(await dialog().getByRole('button',{name:'Potvrdit přečtení',exact:true}).count(),0);await save('02-vehicle-notification');const target='/api/v1/vehicles/'+vehicle.action.vehicle_id;const navigation=p.waitForRequest(r=>new URL(r.url()).pathname===target);await dialog().getByRole('button',{name:'Otevřít vozidlo',exact:true}).click();await navigation;checks.push('Authorized vehicle update read receipt and actual product navigation request to its exact vehicle id');
  await p.goto(origin+'/web/customer.html#notifications/'+vehicle.id);await dialog().getByText(vehicle.body,{exact:true}).waitFor();assert.equal(await dialog().locator('.notification-detail').getAttribute('data-notification-id'),String(vehicle.id));await save('03-push-destination');checks.push('Actual product deep-link opens exact notification detail after authenticated bootstrap');
  const unauth=await make(false);const count=requests.length;await unauth.goto(origin+'/web/customer.html#notifications/'+vehicle.id);await unauth.locator('#authSection').waitFor();assert.equal(await unauth.locator('dialog.notification-dialog').count(),0);assert(!(await unauth.locator('body').innerText()).includes(vehicle.body));assert(!requests.slice(count).some(x=>x.startsWith('/api/v1/notifications')));checks.push('Unauthenticated deep-link stays at login without fetching or exposing private notice');
  assert.deepEqual(errors,[]);const pins={};for(const f of ['web/notification-center.js','web/notification-center.css','web/admin-messages.js','web/index.html','web/legacy-app.js','web/sw.js'])pins[f]=crypto.createHash('sha256').update(fs.readFileSync(path.join(__dirname,'../..',f))).digest('hex');const result={status:'PASS',at:new Date().toISOString(),checks,sourcePins:pins,limits:['Synthetic session precondition, actual loopback API and full product HTML','Vehicle detail endpoint absent from fixture: exact navigation request is verified, complete vehicle detail is not','Worker event routing tested separately; actual provider-to-device push not tested'],vehicle_notification_id:vehicle.id};fs.writeFileSync(path.join(out,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
 }catch(e){if(p){await p.screenshot({path:path.join(out,'failure.png'),fullPage:true});fs.writeFileSync(path.join(out,'failure.txt'),e.stack+'\n'+await p.locator('body').innerText());}throw e;}finally{for(const c of contexts)await c.close();await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
